"""ReAct-style tool loop with a no-progress brake, not only a step cap."""

import hashlib
import json
import os
from collections import Counter

from openai import OpenAI

client = OpenAI(api_key=os.environ["OPENAI_API_KEY"])
MAX_STEPS = 50
IDENTICAL_ACTION_ALLOWANCE = 3
TOOLS = [{"type": "function", "function": {"name": "web_search"}}]


class NoProgress(RuntimeError):
    """The loop is spending money without changing state."""


def action_fingerprint(name: str, args: dict) -> str:
    payload = json.dumps([name, args], sort_keys=True).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def dispatch(name: str, args: dict) -> str:
    return TOOL_IMPLS[name](**args)


def run(question: str) -> str:
    messages = [{"role": "user", "content": question}]
    seen_actions: Counter[str] = Counter()
    for _ in range(MAX_STEPS):
        reply = client.chat.completions.create(
            model="gpt-4.1", messages=messages, tools=TOOLS
        )
        choice = reply.choices[0].message
        if not choice.tool_calls:
            return choice.content
        messages.append(choice)
        for call in choice.tool_calls:
            args = json.loads(call.function.arguments)
            fingerprint = action_fingerprint(call.function.name, args)
            seen_actions[fingerprint] += 1
            if seen_actions[fingerprint] > IDENTICAL_ACTION_ALLOWANCE:
                raise NoProgress(
                    f"{call.function.name} called {seen_actions[fingerprint]} times "
                    "with identical arguments: halting before the step cap"
                )
            result = dispatch(call.function.name, args)
            messages.append(
                {"role": "tool", "tool_call_id": call.id, "content": result}
            )
    return messages[-1]["content"]
